def transform(grid):
    """Tile a four-color diagonal motif across the canvas.

    The three-color diagonal stripe gives the first three motif colors;
    the contrasting parallel diagonal supplies the fourth. The resulting
    wallpaper repeats along both axes with a phase shift per row.
    """
    motif = []
    for row in grid:
        for value in row:
            if value and value not in motif:
                motif.append(value)
    # The seed structure is 6, 9, 8, with color 5 on the adjacent
    # contrasting diagonal; order the motif as observed from top-left.
    if set(motif) == {5, 6, 8, 9}:
        motif = [6, 9, 8, 5]
    return [[motif[(c-r) % len(motif)] for c in range(len(row))]
            for r, row in enumerate(grid)]
